import clsx from 'clsx'
import { useValues } from 'kea'
import { useCallback, useEffect, useState } from 'react'

import { IconArrowDown, IconArrowLeft, IconArrowRight, IconArrowUp, IconDrag, IconTrash } from '@posthog/icons'
import { LemonButton, LemonDivider } from '@posthog/lemon-ui'

import { richContentEditorLogic } from 'lib/components/RichContentEditor/richContentEditorLogic'
import { Popover } from 'lib/lemon-ui/Popover'

const GRIP_OFFSET = 6
const GRIP_SIZE = 20

type GripMode = 'row' | 'col'

type TableCommand = 'addRowBefore' | 'addRowAfter' | 'deleteRow' | 'addColumnBefore' | 'addColumnAfter' | 'deleteColumn'

type HoveredCell = {
    rowIndex: number
    colIndex: number
    row: HTMLTableRowElement
    cell: HTMLTableCellElement
    table: HTMLTableElement
}

type MenuAction = {
    label: string
    icon: JSX.Element
    onClick: () => void
    status?: 'danger'
}

function getGripStyle(mode: GripMode, hoveredCell: HoveredCell): React.CSSProperties {
    const tableRect = hoveredCell.table.getBoundingClientRect()
    if (mode === 'row') {
        const rowRect = hoveredCell.row.getBoundingClientRect()
        return {
            top: rowRect.top,
            left: tableRect.left - GRIP_SIZE - GRIP_OFFSET,
            width: GRIP_SIZE + GRIP_OFFSET,
            height: rowRect.height,
        }
    }
    const cellRect = hoveredCell.cell.getBoundingClientRect()
    return {
        top: tableRect.top - GRIP_SIZE - GRIP_OFFSET,
        left: cellRect.left,
        width: cellRect.width,
        height: GRIP_SIZE + GRIP_OFFSET,
    }
}

function GripHandle({
    mode,
    hoveredCell,
    isMenuOpen,
    actions,
    onCloseMenu,
    onClick,
}: {
    mode: GripMode
    hoveredCell: HoveredCell
    isMenuOpen: boolean
    actions: MenuAction[]
    onCloseMenu: () => void
    onClick: () => void
}): JSX.Element {
    return (
        // Wrapper extends from the icon to the table edge, bridging the hover gap so the grip doesn't flicker
        <div
            className="fixed flex items-center justify-center z-0"
            style={getGripStyle(mode, hoveredCell)}
            data-table-grip
        >
            <Popover
                visible={isMenuOpen}
                onClickOutside={onCloseMenu}
                placement={mode === 'row' ? 'right-start' : 'bottom-start'}
                className={mode === 'col' ? 'mt-1' : 'ml-1'}
                overlay={
                    <div className="flex flex-col p-1 min-w-40">
                        {actions.map((action, i) => (
                            <div key={action.label}>
                                {i > 0 && action.status === 'danger' && actions[i - 1]?.status !== 'danger' && (
                                    <LemonDivider className="my-1" />
                                )}
                                <LemonButton
                                    onClick={action.onClick}
                                    icon={action.icon}
                                    status={action.status}
                                    size="small"
                                    fullWidth
                                >
                                    {action.label}
                                </LemonButton>
                            </div>
                        ))}
                    </div>
                }
