    | 'addRowBefore'
    | 'addRowAfter'
    | 'deleteRow'
    | 'addColumnBefore'
    | 'addColumnAfter'
    | 'deleteColumn'

type HoveredCell = {
    rowIndex: number
    colIndex: number
    row: HTMLTableRowElement
    cell: HTMLTableCellElement
    table: HTMLTableElement
}

