            width: GRIP_SIZE + GRIP_OFFSET,
            height: rowRect.height,
        }
    }
    const cellRect = hoveredCell.cell.getBoundingClientRect()
    return {
        top: tableRect.top - GRIP_SIZE - GRIP_OFFSET,
        left: cellRect.left,
        width: cellRect.width,
        height: GRIP_SIZE + GRIP_OFFSET,
    }
}

